import tensorflow as tf

# Compute the median value of an array
def median(values):
  values_tensor = tf.convert_to_tensor(values)
  n = tf.cast(tf.reduce_prod(tf.shape(values_tensor)), tf.float32)
  def median_cond(it, n, odd_sum,even_sum):
    return tf.less(it, n)
  def median_body(it, n, odd_sum,even_sum):
    num = tf.gather(values,[tf.cast(it, tf.int32)])
    if tf.math.equal(tf.math.mod(it,2), 0):
      even_sum = tf.cond(tf.math.equal(it,0),lambda:num,lambda:tf.add(even_sum,num))
    else:
      odd_sum = tf.add(odd_sum,num)
    it = tf.add(it,1)
    return [it, n, odd_sum,even_sum]
  def median_merge(it, n, odd_sum,even_sum):
    return tf.math.divide(tf.add(odd_sum,even_sum),2.)
  it = tf.constant(0)
  odd_sum = 0.
  even_sum = 0.
  return tf.while_loop(median_cond,median_body,median_merge,
                       [it, n, odd_sum,even_sum])  

