from collections import defaultdict
from math import sqrt

# Compute the word frequencies
def get_word_frequencies(tokens):
    frequencies = defaultdict(int)
    for token in tokens:
        frequencies[token] += 1

    return dict(frequencies)

# Compute the document vector
def doc_to_vector(terms, document):
    document_vector = [0] * len(terms)
    freq_list = get_word_frequencies(document)

    for i, term in enumerate(terms):
        if term in freq_list:
            document_vector[i] = freq_list[term]
    return document_vector

# Compute the tf-idf vector
def vectorize(documents):
    terms = set()
    all_vectors = list()
    doc_freqs = defaultdict(int)

    # Create term list and count document frequencies
    for document in documents:
        frequencies = get_word_frequencies(document)
        for token in frequencies:
            terms.add(token)
            doc_freqs[token] += 1

    # Create term-document matrix
    termlist = list(terms)
    for document in documents:
        document_vector = doc_to_vector(termlist, document)
        all_vectors.append(document_vector)

    # Compute IDF for each term
    N = len(documents)
    idf = dict()
    for term in terms:
        idf[term] = log10(N / doc_freqs[term])

    # Generate the TF * IDF vector for each document
    tf_idf_vectors = list()
    for document_vector in all_vectors:
        tf_idf_vector = [0] * len(termlist)
        for i, term in enumerate(termlist):
            tf_idf_vector[i] = document_vector[i] * idf[term]
        tf_idf_vectors.append(tf_idf_vector)

    return termlist, tf_idf_vectors

# Query for documents
def query(query_vector, terms, tf_idf_vectors, documents):
    doc_similarities = []
    for document_vector in tf_idf_vectors:
        similarity = 0
        for tf_idf, query_tf_idf in zip(document_vector, query_vector):
            similarity += tf_idf * query_tf_idf
        magnitude = sqrt(sum([val**2 for val in document_vector])) * sqrt(sum([val**2 for val in query_vector]))
        if not magnitude:
            doc_similarities.append(0)
        else:
            doc_similarities.append(similarity/magnitude)

    return [doc for _, doc in sorted(zip(doc_similarities, documents), reverse=True)]

