            if (rand() % 2 == 0) {
                subset.push_back(data[i]);
            }
        }
        return subset;
    }
    Node* buildTree(vector<Shape> data, int depth) {
        if (depth >= maxDepth || data.size() == 0) {
            return NULL;
        }
        string label = getMajorityLabel(data);
        if (data.size() == 1) {
            Node* leaf = new Node();
            leaf->label = label;
            return leaf;
        }
        int numFeatures = 4;
        int featureIndex = rand() % numFeatures;
        double threshold = getThreshold(data, featureIndex);
        vector<Shape> leftData;
        vector<Shape> rightData;
        for (int i = 0; i < data.size(); i++) {
            if (data[i].label == "triangle") {
                if (data[i].angles < threshold) {
                    leftData.push_back(data[i]);
                } else {
                    rightData.push_back(data[i]);
                }
            } else {
                if (data[i].radius < threshold) {
                    leftData.push_back(data[i]);
                } else {
                    rightData.push_back(data[i]);
                }
            }
        }
        Node* node = new Node();
        node->featureIndex = featureIndex;
        node->threshold = threshold;
        node->left = buildTree(leftData, depth + 1);
        node->right = buildTree(rightData, depth + 1);
        node->label = label;
        return node;
    }
    string traverseTree(Shape shape, Node* node) {
        if (node->left == NULL && node->right == NULL) {
            return node->label;
        }
        if (shape.label == "triangle") {
            if (shape.angles < node->threshold) {
                return traverseTree(shape, node->left);
            } else {
                return traverseTree(shape, node->right);
            }
        } else {
            if (shape.radius < node->threshold) {
                return traverseTree(shape, node->left);
            } else {
                return traverseTree(shape, node->right);
            }
        }
    }
    string getMajorityLabel(vector<Shape> data) {
        int numTriangles = 0;
        int numCircles = 0;
        for (int i = 0; i < data.size(); i++) {
            if (data[i].label == "triangle") {
                numTriangles++;
            } else {
                numCircles++;
            }
        }
        if (numTriangles > numCircles) {
            return "triangle";
        } else {
            return "circle";
        }
    }
    double getThreshold(vector<Shape> data, int featureIndex) {
        double minVal = data[0].area;
        double maxVal = data[0].area;
        for (int i = 1; i < data.size(); i++) {
            if (featureIndex == 0) {
                if (data[i].area < minVal) {
                    minVal = data[i].area;
                }
                if (data[i].area > maxVal) {
                    maxVal = data[i].area;
                }
            } else if (featureIndex == 1) {
                if (data[i].perimeter < minVal) {
                    minVal = data[i].perimeter;
                }
                if (data[i].perimeter > maxVal) {
                    maxVal = data[i].perimeter;
                }
            } else if (featureIndex == 2) {
                if (data[i].radius < minVal) {
                    minVal = data[i].radius;
                }
                if (data[i].radius > maxVal) {
                    maxVal = data[i].radius;
                }
            } else {
                if (data[i].angles < minVal) {
                    minVal = data[i].angles;
                }
                if (data[i].angles > maxVal) {
                    maxVal = data[i].angles;
                }
            }
        }
        return (minVal + maxVal) / 2;
    }
};
