using namespace std;

// Function to preprocess the input text
string preprocess(string text) {
    // Convert to lowercase
    transform(text.begin(), text.end(), text.begin(), ::tolower);

    // Remove punctuation
    string new_text;
    for (auto c : text) {
        if (isalpha(c)) {
            new_text += c;
        }
    }

    return new_text;
}

// Function to read stop words from a file
void read_stop_words(string file_name, unordered_set<string>& stop_words) {
    ifstream infile(file_name);
    string word;
    while (infile >> word) {
        stop_words.insert(word);
    }
}

// Function to split the input text into words
vector<string> split_words(string text) {
    vector<string> words;
    string word;
    for (auto c : text) {
        if (isspace(c)) {
            if (!word.empty()) {
                words.push_back(word);
                word.clear();
            }
        } else {
            word += c;
        }
    }
    if (!word.empty()) {
        words.push_back(word);
    }
    return words;
}

// Function to remove stop words from a list of words
void remove_stop_words(vector<string>& words, unordered_set<string>& stop_words) {
    words.erase(remove_if(words.begin(), words.end(), [&](string word) {
        return stop_words.count(word) > 0;
    }), words.end());
}

// Function to build a frequency table of words in the input text
unordered_map<string, int> build_frequency_table(string text, unordered_set<string>& stop_words) {
    unordered_map<string, int> frequency_table;
    vector<string> words = split_words(preprocess(text));
    remove_stop_words(words, stop_words);
    for (auto word : words) {
        frequency_table[word]++;
    }
    return frequency_table;
}

// Function to calculate the cosine similarity between two vectors
double cosine_similarity(unordered_map<string, int>& v1, unordered_map<string, int>& v2) {
    double dot_product = 0;
    double v1_norm = 0;
    double v2_norm = 0;
    for (auto p1 : v1) {
        if (v2.count(p1.first) > 0) {
            dot_product += p1.second * v2[p1.first];
        }
        v1_norm += p1.second * p1.second;
    }
    for (auto p2 : v2) {
        v2_norm += p2.second * p2.second;
    }
    v1_norm = sqrt(v1_norm);
    v2_norm = sqrt(v2_norm);
    return dot_product / (v1_norm * v2_norm);
}

int main() {
    unordered_set<string> stop_words;
    read_stop_words("stop_words.txt", stop_words);

    string text1 = "Breaking news: Aliens have landed in Central Park!";
    string text2 = "Visitors from another planet have arrived in Central Park!";
    string text3 = "Scientists discover new species of bird in Central Park.";

    unordered_map<string, int> frequency_table1 = build_frequency_table(text1, stop_words);
    unordered_map<string, int> frequency_table2 = build_frequency_table(text2, stop_words);
    unordered_map<string, int> frequency_table3 = build_frequency_table(text3, stop_words);

    double similarity1_2 = cosine_similarity(frequency_table1, frequency_table2);
    double similarity1_3 = cosine_similarity(frequency_table1, frequency_table3);
    double similarity2_3 = cosine_similarity(frequency_table2, frequency_table3);

