To analyze a sentence's syntax and detect passive voice in C++, you can use a natural language processing library like Stanford's CoreNLP or NLTK. Here's an example using CoreNLP:
```
#include <iostream>
#include <core/StanfordCoreNLP.h>
using namespace std;
using namespace stanfordnlp;
int main() {
  // Initialize CoreNLP
  StanfordCoreNLP pipeline;
  pipeline.setOption("annotators", "tokenize,ssplit,pos,lemma,parse,depparse");
  // Analyze sentence
  string sentence = "The ball was kicked by the boy.";
  auto doc = pipeline.annotate(sentence);
  auto& sentences = doc.sentences();
  auto& tokens = sentences[0].tokens();
  auto& dependencies = sentences[0].enhancedPlusPlusDependencies();
  // Check for passive voice
  bool isPassive = false;
  for (const auto& dep : dependencies) {
    if (dep.reln() == "nsubjpass" || dep.reln() == "auxpass") {
      isPassive = true;
      break;
    }
  }
  cout << (isPassive ? "The sentence is in passive voice." : "The sentence is not in passive voice.") << endl;
  return 0;
}
```
