    return sorted_population[:num_parents]

def crossover(parent1, parent2):
    crossover_point = random.randint(1, parent1.bird.weights_input_hidden.size - 1)
    child_bird = NeuralBird(parent1.bird.input_size, parent1.bird.hidden_size, parent1.bird.output_size)
    child_bird.weights_input_hidden = np.concatenate((parent1.bird.weights_input_hidden[:, :crossover_point],
                                                     parent2.bird.weights_input_hidden[:, crossover_point:]), axis=1)
    child_bird.weights_hidden_output = np.concatenate((parent1.bird.weights_hidden_output[:, :crossover_point],
                                                      parent2.bird.weights_hidden_output[:, crossover_point:]), axis=1)
    return Chromosome(child_bird)

def mutation(chromosome, mutation_rate):
    if random.random() < mutation_rate:
        mutation_point = random.randint(0, chromosome.bird.weights_input_hidden.size - 1)
        if mutation_point < chromosome.bird.weights_input_hidden.size / 2:
            chromosome.bird.weights_input_hidden.flat[mutation_point] = random.random()
        else:
            mutation_point -= chromosome.bird.weights_input_hidden.size / 2
            chromosome.bird.weights_hidden_output.flat[mutation_point] = random.random()
    return chromosome

def evaluate_fitness(chromosome, environment):
