class Word2VecRec:
    def __init__(self, vector_size=100, window=5):
        self.vector_size = vector_size
        self.window = window
        self.word_vectors = {}

    def fit(self, df):
        # Preprocessing and building vocabulary
        sentences = df['text'].apply(lambda x: x.split()).tolist()
        vocabulary = set(word for sentence in sentences for word in sentence)
        vocab_size = len(vocabulary)

        # Initialize word vectors randomly
        for word in vocabulary:
            self.word_vectors[word] = np.random.rand(self.vector_size)

        # Training the Word2Vec model
        for sentence in sentences:
            for i, target_word in enumerate(sentence):
                context_words = sentence[max(0, i - self.window):i] + sentence[i+1:min(len(sentence), i + self.window + 1)]
                for context_word in context_words:
                    self.word_vectors[target_word] += self.word_vectors[context_word]
                    self.word_vectors[context_word] += self.word_vectors[target_word]

        # Normalizing word vectors
        for word in vocabulary:
            self.word_vectors[word] /= np.linalg.norm(self.word_vectors[word])

    def predict(self, df, top_n):
        predictions = {}
        for word in df['text']:
            if word in self.word_vectors:
                similarities = {}
                for vocab_word in self.word_vectors:
                    if vocab_word != word:
                        similarities[vocab_word] = np.dot(self.word_vectors[word], self.word_vectors[vocab_word])
                top_similar_words = sorted(similarities, key=similarities.get, reverse=True)[:top_n]
                predictions[word] = top_similar_words
        return predictions

