import torch

class TensorType:
    def __init__(self, shape):
        self.shape = shape

    @staticmethod
    def l2_grad(
        diffs: TensorType["num_samples", "num_keypoints", 2], scalar: float = 1.0
    ) -> TensorType["num_samples", "num_keypoints", 2]:
        if torch.allclose(diffs, torch.zeros_like(diffs)):
            # If all elements of diffs are close to zero, return the input tensor diffs
            return diffs
        else:
            # Calculate the L2 norm of the input tensor along the last dimension
            norm = torch.linalg.norm(diffs, dim=2, keepdim=True)
            # Apply the scalar factor to the normalized tensor
            result = diffs / norm * scalar
            return result
```

