import numpy as np

class VonMisesFisher:
    def __init__(self, kappa, mu):
        self.kappa = kappa
        self.mu = mu
        self.pdf_constant = 1 / (4 * np.pi * np.sinh(kappa))

    def pdf(self, X):
        """
        Computes the probability density function (pdf) of the von Mises-Fisher distribution for a single point X on the sphere.
        :param X: np.ndarray(3,) - A point on the unit sphere
        :return: scalar : np.float64 - Probability density at point X
        """
        if self.kappa == 0:
            return .25 / np.pi
        else:
            return self.pdf_constant * np.exp(self.kappa * (self.mu.dot(X) - 1.))

    def pdfs(self, X):
        """
        Computes the probability density function (pdf) of the von Mises-Fisher distribution for multiple points X on the sphere.
        :param X: np.ndarray - (n, 3) - Points on the unit sphere
        :return: Pdfs = np.ndarray - (n, 1) - Probability densities for each point in X
        """
        if self.kappa == 0:
            return (.25 / np.pi) * np.ones((X.shape[0], 1))
        else:
            return self.pdf_constant * np.exp(self.kappa * (X.dot(self.mu) - 1.)).reshape(-1, 1)

# Example usage
kappa = 2.0
mu = np.array([1, 0, 0])  # Mean direction along the x-axis
vmf = VonMisesFisher(kappa, mu)
point = np.array([0, 1, 0])  # Point on the unit sphere
print(vmf.pdf(point))  # Compute pdf for a single point
points = np.array([[0, 1, 0], [0, 0, 1], [1, 0, 0]])  # Multiple points on the unit sphere
print(vmf.pdfs(points))  # Compute pdfs for multiple points
