    file.write('<ipestyle name="transform" family="transform" extends="basic">\n')
    file.write('<transform name="M">\n')
    for row in M:
        file.write(' '.join(map(str, row)) + '\n')
    file.write('</transform>\n')
    file.write('</ipestyle>\n')
    file.write('</ipe>\n')
