```python
import numpy as np

class TFFMBase:
    def __init__(self, rank, n_features, n_fields, task='classification', learning_rate=0.1, reg=0.1):
        self.rank = rank
        self.n_features = n_features
        self.n_fields = n_fields
        self.task = task
        self.learning_rate = learning_rate
        self.reg = reg
        self.weights = np.random.normal(size=(n_features, n_fields, rank))

    def _predict_instance(self, x):
        pred = 0.0
        for i in range(self.n_features):
            for j in range(i+1, self.n_features):
                pred += np.dot(self.weights[i, x[i], :], self.weights[j, x[j], :])
        return pred

    def fit(self, X, y):
        for _ in range(10):  # Number of iterations for training
            for i in range(len(X)):
                pred = self._predict_instance(X[i])
                loss = pred - y[i]
                for j in range(self.n_features):
                    for k in range(self.rank):
                        self.weights[j, X[i][j], k] -= self.learning_rate * (loss * self.weights[j, X[i][j], k] + self.reg * self.weights[j, X[i][j], k])

    def predict(self, X):
        predictions = []
        for i in range(len(X)):
            pred = self._predict_instance(X[i])
            predictions.append(pred)
        return np.array(predictions)

    def evaluate(self, X, y):
        predictions = self.predict(X)
        if self.task == 'classification':
            return np.mean((predictions > 0) == y)
        elif self.task == 'regression':
            return np.mean((predictions - y) ** 2)
```
This `TFFMBase` class provides a basic implementation of FFM for classification and regression tasks. The class constructor takes parameters such as `rank` (number of latent factors), `n_features` (number of features), `n_fields` (number of fields), `task` (classification or regression), `learning_rate`, and `reg` (regularization parameter). The `fit` method trains the FFM model, the `predict` method makes predictions, and the `evaluate` method computes the performance metric based on the task type. The FFM model is trained using stochastic gradient descent with L2 regularization.

