import nnabla.solvers as S
import numpy as np

class CustomAdamSolver(S.Solver):
    def __init__(self, lr=0.001, beta1=0.9, beta2=0.999, eps=1e-8):
        super(CustomAdamSolver, self).__init__()
        self.lr = lr
        self.beta1 = beta1
        self.beta2 = beta2
        self.eps = eps
        self.t = 0
        self.m = {}
        self.v = {}

    def set_parameters(self, params):
        super(CustomAdamSolver, self).set_parameters(params)
        for param in params:
            self.m[param] = np.zeros_like(param.data)
            self.v[param] = np.zeros_like(param.data)

    def zero_grad(self):
        for key in self.m:
            self.m[key].fill(0)
            self.v[key].fill(0)

    def update(self):
        self.t += 1
        lr_t = self.lr * (np.sqrt(1 - self.beta2 ** self.t) / (1 - self.beta1 ** self.t))

        for key, param in self.get_parameters().items():
            grad = param.grad
            self.m[key] = self.beta1 * self.m[key] + (1 - self.beta1) * grad
            self.v[key] = self.beta2 * self.v[key] + (1 - self.beta2) * grad ** 2
            param.data -= lr_t * self.m[key] / (np.sqrt(self.v[key]) + self.eps)

# Test case
class RefSolver:
    def __init__(self, lr=0.001, beta1=0.9, beta2=0.999, eps=1e-8):
        self.lr = lr
        self.beta1 = beta1
        self.beta2 = beta2
        self.eps = eps
        self.t = 0
        self.m = {}
        self.v = {}

    def set_parameters(self, params):
        for param in params:
            self.m[param] = np.zeros_like(param)
            self.v[param] = np.zeros_like(param)

    def zero_grad(self):
        for key in self.m:
            self.m[key].fill(0)
            self.v[key].fill(0)

    def update(self, params):
        self.t += 1
        lr_t = self.lr * (np.sqrt(1 - self.beta2 ** self.t) / (1 - self.beta1 ** self.t))

        for key, param in params.items():
            grad = param
            self.m[key] = self.beta1 * self.m[key] + (1 - self.beta1) * grad
            self.v[key] = self.beta2 * self.v[key] + (1 - self.beta2) * grad ** 2
            params[key] -= lr_t * self.m[key] / (np.sqrt(self.v[key]) + self.eps)

# Test the custom solver
def solver_tester(custom_solver, ref_solver, params, grad, expected_params):
    custom_solver.set_parameters(params)
    ref_solver.set_parameters(params)

    custom_solver.zero_grad()
    ref_solver.zero_grad()

    for key, param in params.items():
        param.grad = grad[key]

    custom_solver.update()
    ref_solver.update(params)

    for key, param in params.items():
        assert np.allclose(param, expected_params[key])

# Usage
