import numpy as np

class SimpleGameEnvironment:
    def __init__(self, grid):
        self.grid = grid
        self.num_rows = len(grid)
        self.num_cols = len(grid[0])
        self.initial_state = self.find_initial_state()
        self.goal_state = self.find_goal_state()

    def find_initial_state(self):
        for i in range(self.num_rows):
            for j in range(self.num_cols):
                if self.grid[i][j] == "E":
                    return (i, j)

    def find_goal_state(self):
        for i in range(self.num_rows):
            for j in range(self.num_cols):
                if self.grid[i][j] == "G":
                    return (i, j)

    def is_valid_move(self, state, action):
        i, j = state
        if action == "up" and i > 0:
            return self.grid[i - 1][j] != "O"
        elif action == "down" and i < self.num_rows - 1:
            return self.grid[i + 1][j] != "O"
        elif action == "left" and j > 0:
            return self.grid[i][j - 1] != "O"
        elif action == "right" and j < self.num_cols - 1:
            return self.grid[i][j + 1] != "O"
        return False

    def step(self, state, action):
        if not self.is_valid_move(state, action):
            return state, -1, False

        i, j = state
        if action == "up":
            next_state = (i - 1, j)
        elif action == "down":
            next_state = (i + 1, j)
        elif action == "left":
            next_state = (i, j - 1)
        else:  # action == "right"
            next_state = (i, j + 1)

        if self.grid[next_state[0]][next_state[1]] == "O":
            return next_state, -10, True
        elif next_state == self.goal_state:
            return next_state, 10, True
        else:
            return next_state, -1, False

    def reset(self):
        return self.initial_state

