import numpy as np

class bLVNet_TAM:
    def __init__(self, learning_rate, threshold):
        self.learning_rate = learning_rate
        self.threshold = threshold
        self.weights = None
        self.bias = None

    def sigmoid(self, x):
        return 1 / (1 + np.exp(-x))

    def train(self, X, y, max_iterations):
        num_features = X.shape[1]
        self.weights = np.random.rand(num_features)
        self.bias = np.random.rand()

        temperature = 1.0
        for _ in range(max_iterations):
            perturbed_weights = self.weights + np.random.normal(0, temperature, num_features)
            perturbed_bias = self.bias + np.random.normal(0, temperature)

            y_pred = self.sigmoid(np.dot(X, perturbed_weights) + perturbed_bias)
            error = np.mean((y_pred - y) ** 2)

            if error < self.threshold:
                self.weights = perturbed_weights
                self.bias = perturbed_bias
            else:
                acceptance_prob = np.exp((self.threshold - error) / temperature)
                if np.random.rand() < acceptance_prob:
                    self.weights = perturbed_weights
                    self.bias = perturbed_bias

            temperature *= 0.95  # Cooling schedule

    def predict(self, X):
        return np.round(self.sigmoid(np.dot(X, self.weights) + self.bias))
