import numpy as np

class Qubit:
    def __init__(self):
        self.state = np.array([1, 0])  # Initialize qubit in |0> state

    def apply_gate(self, gate_matrix):
        self.state = np.dot(gate_matrix, self.state)  # Apply gate to the qubit

    def measure(self):
        probabilities = np.abs(self.state) ** 2
        outcome = np.random.choice([0, 1], p=probabilities)  # Perform measurement
        self.state = np.array([0, 1]) if outcome else np.array([1, 0])  # Collapse qubit to measured state
        return outcome

class QuantumRegister:
    def __init__(self, num_qubits):
        self.qubits = [Qubit() for _ in range(num_qubits)]  # Initialize qubits in the register

    def add_qubit(self):
        self.qubits.append(Qubit())  # Add a qubit to the register

    def apply_gate(self, gate_matrix):
        for qubit in self.qubits:
            qubit.apply_gate(gate_matrix)  # Apply gate to each qubit in the register

    def measure_all(self):
        measurements = [qubit.measure() for qubit in self.qubits]  # Measure all qubits in the register
        return measurements

# Example usage
qr1 = QuantumRegister(2)
qr1.apply_gate(np.array([[0, 1], [1, 0]]))  # Apply X gate to the first qubit
measurement_results = qr1.measure_all()  # Measure all qubits in the register
print(measurement_results)  # Print measurement results
```
