import numpy as np

def opposite_hemisphere_vertices(vertices, dist_thresh=None):
    equator_vertices = [v for v in vertices if v[2] == 0]  # Select vertices on the equator (z=0)

    if dist_thresh is None:
        dist_thresh = np.finfo(float).eps  # Use default threshold based on input data type

    opposite_indices = []
    for i, v in enumerate(equator_vertices):
        opposite = False
        for v_dash in vertices:
            if v_dash[2] != 0:  # Skip vertices not on the equator
                continue
            if np.linalg.norm(np.array(v) * -1 - np.array(v_dash)) <= dist_thresh:
                opposite = True
                break
        if opposite:
            opposite_indices.append(vertices.index(v))

    return opposite_indices
