import tensorflow as tf
from tensorflow.contrib.slim.nets import resnet_v2

def model_fn(features, labels, mode):
    # Create ResNet-18 model
    x, end_points = resnet_v2.resnet_v2_18(features, num_classes=None, is_training=(mode == tf.estimator.ModeKeys.TRAIN))

    if mode == tf.estimator.ModeKeys.TRAIN:
        # Define loss function
        loss = tf.losses.sparse_softmax_cross_entropy(labels=labels, logits=x)

        # Define optimizer
        optimizer = tf.train.AdamOptimizer(learning_rate=0.001)

        # Minimize loss
        train_op = optimizer.minimize(loss, global_step=tf.train.get_global_step())

        return tf.estimator.EstimatorSpec(mode=mode, loss=loss, train_op=train_op)

    if mode == tf.estimator.ModeKeys.EVAL:
        # Define evaluation metrics
        predictions = tf.argmax(input=x, axis=1)
        accuracy = tf.metrics.accuracy(labels=labels, predictions=predictions)
        eval_metric_ops = {'accuracy': accuracy}

        return tf.estimator.EstimatorSpec(mode=mode, loss=loss, eval_metric_ops=eval_metric_ops)

    if mode == tf.estimator.ModeKeys.PREDICT:
        # Define custom head for transfer learning
        custom_head = tf.layers.dense(inputs=end_points['pool5'], units=4, activation=tf.nn.relu)

        return tf.estimator.EstimatorSpec(mode=mode, predictions=custom_head)
```

