import numpy as np
from typing import Tuple, Generator

def chunk_data_image_generator(img: np.ndarray,
                               chunk_size: Tuple[int, int] = (500, 500),
                               displacement: Tuple[int, int] = (250, 250)) -> Generator[np.ndarray, None, None]:
    img_height, img_width = img.shape
    chunk_height, chunk_width = chunk_size
    displacement_y, displacement_x = displacement

    for y in range(0, img_height - chunk_height + 1, displacement_y):
        for x in range(0, img_width - chunk_width + 1, displacement_x):
            chunk = img[y:y+chunk_height, x:x+chunk_width]
            yield chunk

    # Handle leftover data at the edges of the image
    if img_height % chunk_height != 0:
        for x in range(0, img_width - chunk_width + 1, displacement_x):
            chunk = img[img_height - chunk_height:img_height, x:x+chunk_width]
            yield chunk

    if img_width % chunk_width != 0:
        for y in range(0, img_height - chunk_height + 1, displacement_y):
            chunk = img[y:y+chunk_height, img_width - chunk_width:img_width]
            yield chunk

    if img_height % chunk_height != 0 and img_width % chunk_width != 0:
        chunk = img[img_height - chunk_height:img_height, img_width - chunk_width:img_width]
        yield chunk
