import numpy as np

def handle_byte_order(fh):
    endian_str = '<'  # Default little-endian byte order
    is_byteorder_specified = False
    byteorder = ''  # Placeholder for specified byte order

    hi = np.array(memoryview(fh.read(4 * 40))).view(np.int32).copy()
    hs = np.array(memoryview(fh.read(24 * 8))).view(np.dtype('|S8')).copy()

    def is_valid_byteorder(arr):
